(function(){"use strict";tinymce.PluginManager.requireLangPack("bsicons");let iconsData=[];let isDataLoaded=false;if(!window._bsIconsListenerAttached){document.addEventListener("click",(function(e){const btn=e.target.closest(".tox-bs-icon-btn");if(btn){e.preventDefault();e.stopPropagation();const iconClass=btn.getAttribute("data-icon");if(tinymce.activeEditor){tinymce.activeEditor.insertContent(`<i class="bi ${iconClass}"></i>&nbsp;`);tinymce.activeEditor.windowManager.close()}}}));window._bsIconsListenerAttached=true}tinymce.PluginManager.add("bsicons",(function(editor,url){const _=text=>editor.translate(text);const fetchIconsData=async()=>{if(isDataLoaded)return;try{const response=await fetch(url+"/bridge.php");if(response.ok){iconsData=await response.json();isDataLoaded=true}}catch(error){console.error(_("Error loading icons via bridge.php:"),error)}};fetchIconsData();const generateGridHtml=(filter="")=>{let html='<div style="display: flex; flex-wrap: wrap; gap: 8px; padding: 10px; justify-content: center; max-height: 400px; overflow-y: auto;">';const filteredIcons=filter===""?iconsData:iconsData.filter((item=>item.name.toLowerCase().includes(filter.toLowerCase())||item.icon.toLowerCase().includes(filter.toLowerCase())));if(filteredIcons.length===0){return`<div style="padding: 20px; text-align: center; color: #666;">${_("No icon found or loading...")}</div>`}filteredIcons.forEach((item=>{html+=`\n                    <button type="button" \n                            class="tox-button tox-button--secondary tox-bs-icon-btn" \n                            data-icon="${item.icon}" \n                            title="${item.name}"\n                            style="width: 42px; height: 42px; font-size: 20px; display: flex; align-items: center; justify-content: center; cursor: pointer; padding: 0;">\n                        <i class="bi ${item.icon}" style="pointer-events: none;"></i>\n                    </button>\n                `}));html+="</div>";return html};const openDialog=function(){if(!isDataLoaded){editor.notificationManager.open({text:_("Loading icons..."),type:"info",timeout:2e3});return}const dialogConfig={title:_("Insert Bootstrap Icons"),size:"large",body:{type:"panel",items:[{type:"input",name:"search",placeholder:_("Search (e.g., star, check, user)...")},{type:"htmlpanel",name:"iconGrid",html:generateGridHtml()}]},buttons:[{type:"cancel",name:"close",text:_("Close")}],onChange:(api,details)=>{if(details.name==="search"){api.setData({iconGrid:generateGridHtml(api.getData().search)})}}};editor.windowManager.open(dialogConfig)};editor.ui.registry.addIcon("bootstrap",`\n            <svg width="24" height="24" viewBox="0 0 16 16" xmlns="http://www.w3.org/2000/svg">\n                <path fill="currentColor" fill-rule="evenodd" d="M5.062 12h3.475c1.804 0 2.888-.908 2.888-2.396 0-1.102-.761-1.916-1.904-2.034v-.1c.832-.14 1.482-.93 1.482-1.816 0-1.3-.955-2.11-2.542-2.11H5.062v8.456zm.925-5.156v-3.15h1.258c1.156 0 1.815.484 1.815 1.582 0 1.05-.658 1.568-1.745 1.568H5.987zm0 4.113V7.781h1.53c1.205 0 1.915.54 1.915 1.582 0 1.054-.705 1.594-1.92 1.594H5.987z"/>\n                <path fill="currentColor" fill-rule="evenodd" d="M0 4a4 4 0 0 1 4-4h8a4 4 0 0 1 4 4v8a4 4 0 0 1-4 4H4a4 4 0 0 1-4-4V4zm4-3a3 3 0 0 0-3 3v8a3 3 0 0 0 3 3h8a3 3 0 0 0 3-3V4a3 3 0 0 0-3-3H4z"/>\n            </svg>\n        `);editor.ui.registry.addButton("bsicons",{icon:"bootstrap",tooltip:_("Bootstrap Icons"),onAction:openDialog});editor.ui.registry.addMenuItem("bsicons",{icon:"bootstrap",text:_("Insert Bootstrap Icons"),onAction:openDialog});editor.on("PreInit",(function(){const bsIconsCss="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css";if(editor.contentCSS){editor.contentCSS.push(bsIconsCss)}else{editor.settings.content_css=(editor.settings.content_css?editor.settings.content_css+",":"")+bsIconsCss}if(!document.querySelector(`link[href="${bsIconsCss}"]`)){const link=document.createElement("link");link.rel="stylesheet";link.href=bsIconsCss;document.head.appendChild(link)}}));return{getMetadata:()=>({name:"Bootstrap Icons Fetcher for TinyMCE 7",url:"https://magix-cms.com"})}}))})();